import { BlockRendererProps } from '@/types.js'
import { useMemo, ClipboardEvent, KeyboardEvent, useRef } from 'react'
import { EditorSelection } from '@codemirror/state'
import type { ReactCodeMirrorRef } from '@uiw/react-codemirror'
import { createMinimalMarkdownConfig } from '@/utils/codemirror.js'
import { BlockEditor } from '@/components/BlockEditor.js'
import { useUIStateBlock } from '@/data/globalState.js'
import { editorSelection, focusBlock } from '@/data/properties.js'
import {
  pasteChordIntent,
  pasteEditModeMultilineText,
  planEditModeMultilinePaste,
  planSingleBlockPaste,
  resolvePasteWithMediaCapture,
} from '@/paste/operations.js'
import type { PasteRequest } from '@/paste/decision.js'
import { tryPasteAsMoveAt } from '@/paste/moveOnPasteVerb.js'
import type { ClipboardPayload } from '@/paste/clipboardPayload.js'
import { readPasteEventContent } from '@/paste/pasteEventContent.js'
import { useRepo } from '@/context/repo.js'
import { useAppRuntime } from '@/extensions/runtimeContext.js'
import { codeMirrorExtensionsFacet } from '@/editor/codeMirrorExtensions.js'
import { createFieldCreationKeydownExtension } from './fieldCreationKeydown.js'
import { useBlockContext } from '@/context/block.js'
import { useBlockTitleTextClass } from './blockTitleText.js'
import type { Block } from '@/data/block.js'
import type { Repo } from '@/data/repo.js'

/**
 * Does an EDITOR-surface paste (this component's `handlePaste`) complete a
 * pending cut→move rather than inserting text?
 *
 * Resolved through `resolvePasteMoveTarget` with `placement: 'sibling'`,
 * matching what `pasteEditModeMultilineText` passes to its own
 * `resolveRootDestination`. 'sibling' does NOT mean "always a sibling":
 * that placement only suppresses the visible-children rule, and the root
 * rules still apply. This used to hardcode a sibling target, which moved
 * the cut blocks out of the rendered surface whenever the edited block WAS
 * the render-scope root — they left the source and never visibly arrived.
 * Hence `scopeRootId` is threaded in.
 *
 * Extracted from `handlePaste` so it's directly testable: rendering a live
 * CodeMirror instance to exercise a real `ClipboardEvent` isn't practical
 * in this suite (no existing harness renders `BlockEditor`/`CodeMirror`
 * with a working view + dispatch), so `CodeMirrorContentRenderer.test.ts`
 * calls this function directly against a real repo instead. `handlePaste`
 * itself just calls this and returns early on `true` — same production
 * code path either way.
 */
export const resolveEditorPasteMove = (
  repo: Repo,
  block: Block,
  payload: ClipboardPayload | null,
  scopeRootId: string | undefined,
  intent: PasteRequest['intent'] = 'split',
): Promise<boolean> =>
  // `single-block` is Cmd/Ctrl+Shift+V — "insert the clipboard text
  // verbatim into this block". Completing a cut there would relocate the
  // source blocks and insert nothing at the caret, taking the explicit
  // command away from the user. The decision lives in here rather than in
  // `handlePaste` so it's reachable from a test: this whole function is
  // extracted for that reason (see the doc above).
  tryPasteAsMoveAt(
    repo, block, 'after', scopeRootId,
    intent === 'single-block' ? null : payload,
    'sibling',
  )

export function CodeMirrorContentRenderer({block}: BlockRendererProps) {
  const repo = useRepo()
  const runtime = useAppRuntime()
  const uiStateBlock = useUIStateBlock()
  const blockContext = useBlockContext()
  // The editor draws the block's own text too, so it carries the same title
  // typography as the read renderer — otherwise a page title would shrink to
  // body size the moment you clicked into it. CodeMirror's theme sets
  // `fontSize: 'inherit'`, so the class on the wrapper reaches the editor.
  const titleClass = useBlockTitleTextClass(block)
  const editorRef = useRef<ReactCodeMirrorRef>(null)
  // The paste ClipboardEvent carries no modifier state, so we latch the
  // most recent paste chord's intent on keydown and read it back in
  // handlePaste. Cmd/Ctrl+Shift+V ('single-block') drops text into the
  // current block verbatim; plain Cmd/Ctrl+V ('split') keeps the
  // existing outline-splitting behavior.
  const pasteIntentRef = useRef<'split' | 'single-block'>('split')

  const extensions = useMemo(() => {
    const fieldCreationExtension = createFieldCreationKeydownExtension(block, repo)
    const pluginExtensions = runtime.read(codeMirrorExtensionsFacet)({repo, block})
    return createMinimalMarkdownConfig([...pluginExtensions, fieldCreationExtension])
  }, [block, repo, runtime])

  // Latch the paste chord's Shift state before the paste event fires
  // (paste events can't see modifiers). Capture phase so we run before
  // CodeMirror's own keydown handling.
  const handleKeyDownCapture = (e: KeyboardEvent<HTMLDivElement>) => {
    const intent = pasteChordIntent(e)
    if (intent) pasteIntentRef.current = intent
  }

  const handlePaste = async (e: ClipboardEvent<HTMLDivElement>) => {
    e.stopPropagation()
    // Read-only editors leave paste to the browser (a no-op on a
    // non-editable surface) — matches the historical single-block guard.
    if (repo.isReadOnly) return
    const {text, html, files: fileList, payload, hasAnything} = readPasteEventContent(e)
    if (!hasAnything) return

    // Latch + reset the chord intent — the paste event can't see modifiers,
    // so the keydown handler latched it. `preventDefault` MUST run
    // synchronously or the browser's native paste fires first; the editor
    // always takes over the paste.
    const intent = pasteIntentRef.current
    pasteIntentRef.current = 'split'
    e.preventDefault()

    // Is this a cut being completed? Checked before any of the
    // paste-decision machinery below: a move relocates the ORIGINAL blocks
    // rather than inserting text at all, and cut→paste means move whichever
    // surface the paste lands on — the clipboard text IS those blocks, so
    // inserting it as text would duplicate them. This is the mouse-driven
    // path (click a destination to enter edit mode, then ⌘V). If the move
    // completes (or is refused as a would-be cycle — see `pasteAsMoveImpl`),
    // the paste is fully handled and nothing below should also run.
    if (await resolveEditorPasteMove(repo, block, payload, blockContext.scopeRootId, intent)) {
      return
    }
    if (!text && fileList.length === 0) return

    // Read the live editor state once: the decision is SYNCHRONOUS (`runSync`),
    // so it resolves before any `await` below and the caret it keys on can't
    // move between this read and the dispatch. (When the decision was async this
    // had to be split into a pre-decision caret snapshot + a post-decision
    // re-read, because an override could await and move the caret mid-flight.)
    const editorView = editorRef.current?.view
    if (!editorView) return
    const selection = editorView.state.selection.main
    const caret = {
      line: editorView.state.doc.lineAt(selection.from).number,
      lineCount: editorView.state.doc.lines,
      from: selection.from,
      to: selection.to,
    }

    // The paste verb decides how the clipboard lands; with no plugin
    // contributions this returns `defaultPasteDecision`, i.e. the previous
    // hardcoded behavior. It's a pure, synchronous policy — an override may key
    // on the paste-time position (title line 1 vs body line 2+) but must decide
    // synchronously. `decision.text` lets it rewrite the content (e.g. CSV →
    // markdown) before it's applied.
    const request: PasteRequest = {text, html, files: fileList, intent, surface: 'editor', caret}
    // Resolve the decision, capturing any pasted media first (async) — its `!((id))`
    // embed text is spliced into the paste below, so the attachment lands at the caret
    // per the text policy (NOT a forced child block). The capture verb is the
    // attachments plugin's effect; this renderer never imports it. `null` ⇒ nothing to
    // paste (no embeds + no text, or a plugin returned media without files).
    const workspaceId = block.peek()?.workspaceId ?? repo.activeWorkspaceId ?? ''
    const resolved = await resolvePasteWithMediaCapture(runtime, request, {repo, workspaceId})
    if (!resolved) return
    // The capture may have awaited; the editor view can have unmounted in that window.
    if (!editorRef.current?.view) return
    const {decision, text: pasteText} = resolved

    // Re-read the caret: a media capture may have awaited above, so use the live selection.
    const insertAt = editorView.state.selection.main

    if (decision.kind === 'single-block') {
      const plan = planSingleBlockPaste(pasteText, {
        from: insertAt.from,
        to: insertAt.to,
      })
      editorView.dispatch({
        changes: {from: plan.from, to: plan.to, insert: plan.insert},
        selection: EditorSelection.cursor(plan.cursor),
      })
      return
    }

    const plan = planEditModeMultilinePaste(pasteText, editorView.state.doc.toString(), {
      from: insertAt.from,
      to: insertAt.to,
    })
    if (!plan) return

    editorView.dispatch({
      changes: {from: 0, to: editorView.state.doc.length, insert: plan.targetContent},
      selection: EditorSelection.cursor(plan.focusOffsetInTarget),
    })

    const result = await pasteEditModeMultilineText(plan, block, repo, {
      scopeRootId: blockContext.scopeRootId,
    })
    const renderScopeId = typeof blockContext.renderScopeId === 'string'
      ? blockContext.renderScopeId
      : undefined
    if (!result) return

    await uiStateBlock.set(editorSelection, {
      blockId: result.focusBlock.id,
      start: result.focusOffset,
    })
    void focusBlock(uiStateBlock, result.focusBlock.id, {edit: true, renderScopeId})
  }

  return (
    <BlockEditor
      ref={editorRef}
      block={block}
      extensions={extensions}
      className={`km-block-text-editor min-h-[1.7em]${titleClass ? ` ${titleClass}` : ''}`}
      basicSetup={{
        closeBrackets: true,
        lineNumbers: false,
        foldGutter: false,
        dropCursor: false,
        allowMultipleSelections: false,
        indentOnInput: false,
        highlightSelectionMatches: false,
        searchKeymap: false,
        defaultKeymap: false,
        history: false,
        historyKeymap: false,
        highlightActiveLine: false,
        completionKeymap: false,
      }}
      indentWithTab={false}
      onKeyDownCapture={handleKeyDownCapture}
      onPasteCapture={handlePaste}
    />
  )
}
